  ('term', 'hrv', 'שונות קצב הלב', 'Heart Rate Variability (HRV)', array['HRV','שונות קצב לב'], 'ההבדלים הזעירים בזמן שבין פעימת לב אחת לבאה אחריה.', 'HRV הוא מדד עקיף להתאוששות ולפעילות מערכת העצבים האוטונומית. כדאי להשוות את המדד בעיקר לעצמכם לאורך זמן.', 'HRV: מהי שונות קצב הלב?', 'הסבר ברור על HRV, מדידה, התאוששות ומגבלות המדד.', now(), true),
  ('term', 'vo2-max', 'צריכת חמצן מרבית', 'VO₂ Max', array['VO2 Max','VO₂ Max','VOmax'], 'כמות החמצן המרבית שהגוף מסוגל לקלוט ולנצל בזמן מאמץ עצים.', 'VO₂ Max הוא מדד מרכזי לכושר אירובי. בדיקת מאמץ עם ניתוח גזים מדויקת יותר מהערכה של שעון חכם.', 'VO₂ Max: מה זה ולמה זה חשוב?', 'מדריך לצריכת חמצן מרבית, בדיקות, שעונים ושיפור הכושר האירובי.', now(), true),
  ('term', 'zone-2', 'אימון אזור 2', 'Zone 2 Training', array['Zone 2','אזור 2','זון 2'], 'אימון אירובי בעצימות קלה עד בינונית המבוצע באופן ממושך ויציב.', 'אימון Zone 2 מסייע לבנות בסיס אירובי וסבולת. הגדרה לפי סף אישי מדויקת יותר מאחוז קבוע של דופק מרבי.', 'Zone 2: המדריך לאימון אזור 2', 'מהו אימון Zone 2, כיצד מזהים את העצימות ולמי הוא מתאים.', now(), true),
  ('term', 'cgm', 'ניטור גלוקוז רציף', 'Continuous Glucose Monitoring (CGM)', array['CGM','סנסור גלוקוז','ניטור סוכר רציף'], 'חיישן שמודד לאורך היום את רמת הגלוקוז בנוזל הבין־תאי.', 'CGM מציג מגמות גלוקוז לאורך היום. המדידה אינה זהה למדידת דם ויש לפרש אותה בהקשר אישי ורפואי.', 'CGM: מהו ניטור גלוקוז רציף?', 'הסבר על חיישני גלוקוז, אופן המדידה, יתרונות ומגבלות.', now(), true),
  ('term', 'nad-plus', 'NAD+', 'Nicotinamide Adenine Dinucleotide', array['NAD+','NAD'], 'קואנזים תאי המעורב בהפקת אנרגיה, תיקון DNA ותהליכים מטבוליים.', 'NAD+ נמצא במרכז מחקר ההזדקנות. התועלת הקלינית ארוכת הטווח של תוספים המיועדים להעלותו עדיין נחקרת.', 'NAD+: תפקידו בגוף ומה ידוע מהמחקר', 'NAD+, מטבוליזם, הזדקנות והראיות לגבי תוספים.', now(), true),
  ('brand', 'garmin', 'גרמין', 'Garmin', array['Garmin','גרמין'], 'חברת טכנולוגיה המפתחת שעוני ספורט, חיישנים ומוצרי ניווט.', 'מוצרי Garmin מציגים מדדים כמו דופק, HRV, עומס אימונים, שינה והערכת VO₂ Max.', 'Garmin: שעונים, מדדי בריאות וטכנולוגיה', 'מדריך למותג Garmin ולמדדי הבריאות והכושר במוצריו.', now(), true),
